pub fn view_exactly_three(site: Rc<Node>, reason: std::string::String) -> Rc<Outcome<Rc<ViewTriple>>> {
    match (*view_whole_positional_children(site.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: children, .. } => { let __fm = children.clone(); if __fm.len() == 3 { let first = (*__fm)[0].clone(); let second = (*__fm)[1].clone(); let third = (*__fm)[2].clone(); crate::v2_std_diagnostic::outcome_accepted(Rc::new(ViewTriple {
    first: first.clone(),
    second: second.clone(),
    third: third.clone(),
})) } else { view_refusal(reason, site.clone()) } },
}
}

